def blob(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()

def run(*args):
    return subprocess.run(args, check=True, timeout=120, stdout=subprocess.PIPE, text=True).stdout.strip()

def state(unit):
    return run("systemctl", "show", unit, "-p", "ActiveState", "--value")

def apply_delta(raw, delta, directory, *, reverse=False):
    source, dest, diff = [directory / n for n in ("input", "output", "delta")]
    source.write_bytes(raw)
    dest.unlink(missing_ok=True)
    diff.write_text(delta, encoding="utf-8")
    args = ["patch", "--batch", "--fuzz=0", "--no-backup-if-mismatch",
            "--reject-file", str(directory / "reject"), "-o", str(dest)]
    args += ["--reverse"] if reverse else ["--forward"]
    subprocess.run(args + [str(source), str(diff)], check=True, timeout=30,
                   stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return dest.read_bytes()

def verified_local_base(name, raw, directory):
    if blob(raw) == OLD_BLOBS[name]:
        return True
    if name not in PRE_RESOURCE_SHA:
        return False
    for backup in sorted(ROOT.glob(name + ".resource.bak.*"), reverse=True):
        if not backup.is_file():
            continue
        original = backup.read_bytes()
        if hashlib.sha1(original).hexdigest() != PRE_RESOURCE_SHA[name]:
            continue
        if apply_delta(original, PREVIOUS_PATCHES[name], directory) == raw:
            return True
    return False

def stage(name, directory):
    raw = (ROOT / name).read_bytes()
    if not verified_local_base(name, raw, directory):
        raise RuntimeError("Unrecognized installed base; no overwrite: " + name + " sha256=" + hashlib.sha256(raw).hexdigest())
    delta = PATCHES[name]
    if (name == "market_gateway.py" and blob(raw) != OLD_BLOBS[name]
            and b"self.live_timing" not in raw and b"def timing_for(" not in raw):
        delta = LEGACY_MARKET_PATCH
        print("Using verified pre-telemetry market variant", flush=True)
    candidate = apply_delta(raw, delta, directory)
    compile(candidate, name, "exec")
    if blob(raw) == OLD_BLOBS[name] and blob(candidate) != NEW_BLOBS[name]:
        raise RuntimeError("Candidate Git blob mismatch: " + name)
    print("STAGED", name, hashlib.sha256(candidate).hexdigest(), flush=True)
    return raw, candidate

def replace(name, raw):
    target = ROOT / name
    fd, temp = tempfile.mkstemp(prefix=".audit-upgrade-", dir=ROOT)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(raw)
        shutil.copystat(target, temp)
        os.replace(temp, target)
    finally:
        Path(temp).unlink(missing_ok=True)

def market_health():
    with urlopen("http://127.0.0.1:8765/health", timeout=3) as r:
        return r.status == 200 and json.load(r).get("ok") is True

def trade_status(key=None):
    req = Request("http://127.0.0.1:8766/v1/trade/snapshot",
                  headers={"X-Qihui-Access": key} if key else {})
    try:
        with urlopen(req, timeout=3) as r:
            return r.status
    except HTTPError as exc:
        return exc.code

def trade_key():
    for line in Path("/etc/qihui-trade.env").read_text().splitlines():
        if line.startswith("QIHUI_TRADE_ACCESS_KEY="):
            key = line.split("=", 1)[1].strip()
            if len(key) >= 32:
                return key
    raise RuntimeError("Missing private trade key")

def wait_healthy(trade=False, key=None):
    for _ in range(30):
        try:
            if market_health() and state(MARKET) == "active":
                if not trade or (state(TRADE) == "active" and trade_status() == 403 and trade_status(key) == 401):
                    return
        except (OSError, ValueError):
            pass
        time.sleep(1)
    raise RuntimeError("Post-restart health check failed")

def deploy(names, *, check, trade=False):
    if not market_health() or state(MARKET) != "active" or state(TRADE) != "active":
        raise RuntimeError("Existing services not healthy")
    key = trade_key() if trade else None
    if trade and (trade_status() != 403 or trade_status(key) != 401):
        raise RuntimeError("Existing trade authorization check failed")
    before_pid = run("systemctl", "show", TRADE, "-p", "MainPID", "--value")
    with tempfile.TemporaryDirectory(prefix=".audit-stage-", dir=ROOT) as tmp:
        staged = {name: stage(name, Path(tmp)) for name in names}
        if check:
            print("AUDIT_CHECK_OK; no files or services changed", flush=True)
            return
        timer_active = not trade and state(TIMER) == "active"
        backups, changed = {}, []
        unit = TRADE if trade else MARKET
        try:
            if timer_active:
                run("systemctl", "stop", TIMER)
            if not trade and state(PREFETCH) not in ("inactive", "failed"):
                raise RuntimeError("Prefetch is running; retry after it finishes")
            for name, (raw, _) in staged.items():
                if (ROOT / name).read_bytes() != raw:
                    raise RuntimeError("Installed source changed during staging")
                backup = ROOT / (name + ".audit.bak." + str(time.time_ns()))
                shutil.copy2(ROOT / name, backup)
                backups[name] = backup
                print("BACKUP", backup, flush=True)
            try:
                for name, (_, candidate) in staged.items():
                    replace(name, candidate)
                    changed.append(name)
                run("systemctl", "restart", unit)
                wait_healthy(trade, key)
            except BaseException:
                for name in reversed(changed):
                    replace(name, backups[name].read_bytes())
                if changed:
                    run("systemctl", "restart", unit)
                    wait_healthy(trade, key)
                print("AUDIT_ROLLED_BACK", flush=True)
                raise
        finally:
            if timer_active:
                run("systemctl", "start", TIMER)
    print("TRADE_PID", before_pid, run("systemctl", "show", TRADE, "-p", "MainPID", "--value"), flush=True)
    print("AUDIT_TRADE_OK" if trade else "AUDIT_MARKET_OK", flush=True)

def self_test():
    with tempfile.TemporaryDirectory() as tmp:
        for name, expected in NEW_BLOBS.items():
            current = (Path(__file__).parent / name).read_bytes()
            assert blob(current) == expected, name
            old = apply_delta(current, PATCHES[name], Path(tmp), reverse=True)
            assert blob(old) == OLD_BLOBS[name], name
            assert apply_delta(old, PATCHES[name], Path(tmp)) == current, name
            compile(current, name, "exec")
        # Simulate the exact missing contexts reported by the installed VPS.
        name = "market_gateway.py"
        current = (Path(__file__).parent / name).read_bytes()
        base = apply_delta(current, PATCHES[name], Path(tmp), reverse=True)
        for fragment in (
            b"        self.live_timing = {}       # key -> (version, TqSdk observation epoch)\n",
            b"                    self.live_timing.pop(oldest, None)\n",
            b"    def timing_for(self, key, version):\n        with self.condition:\n            record = self.live_timing.get(key)\n            return record[1] if record and record[0] == version else None\n\n",
        ):
            assert base.count(fragment) == 1
            base = base.replace(fragment, b"", 1)
        candidate = apply_delta(base, LEGACY_MARKET_PATCH, Path(tmp))
        assert b"self.pending_disk_writes = OrderedDict()" in candidate
        assert b"def _run_disk_writer(self):" in candidate
        assert b"def timing_for(" not in candidate
        compile(candidate, name, "exec")
    print("AUDIT_PATCH_SELF_TEST_OK")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("mode", choices=("check-market", "apply-market", "check-trade", "apply-trade", "self-test"))
    parser.add_argument("--confirm-simulation-logged-out", action="store_true")
    args = parser.parse_args()
    if args.mode == "self-test":
        self_test()
        return
    if os.geteuid() != 0:
        raise RuntimeError("root required")
    trade = args.mode.endswith("trade")
    check = args.mode.startswith("check")
    if trade and not check and not args.confirm_simulation_logged_out:
        raise RuntimeError("Log out of simulation and reconcile outstanding orders first")
    with open("/run/lock/qihui-audit-upgrade.lock", "a") as lock:
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        deploy(TRADE_FILES if trade else MARKET_FILES, check=check, trade=trade)

if __name__ == "__main__":
    main()
